import{c as o,Q as n,j as i,m as r,g as e,n as a}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"PromptBridge: Cross-Model Prompt Transfer for Large Language Models","description":"","frontmatter":{"url":"https://arxiv.org/abs/2512.01420","title":"PromptBridge: Cross-Model Prompt Transfer for Large Language Models","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2512.0142,"authors":["Yaxuan Wang","Quan Liu","Zhenting Wang","Zichao Li","Wei Wei","Yang Liu","Yujia Bao"],"pdf_path":"pdfs/2512.01420.pdf","published_date":"2025-12-01T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2025-12-01-promptbridge-cross-model-prompt-transfer-2512-01420.md","filePath":"research/papers/2025-12-01-promptbridge-cross-model-prompt-transfer-2512-01420.md","lastUpdated":1785909234000}'),s={name:"research/papers/2025-12-01-promptbridge-cross-model-prompt-transfer-2512-01420.md"};function l(d,t,p,g,m,c){return n(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="promptbridge-cross-model-prompt-transfer-for-large-language-models" tabindex="-1">PromptBridge: Cross-Model Prompt Transfer for Large Language Models <a class="header-anchor" href="#promptbridge-cross-model-prompt-transfer-for-large-language-models" aria-label="Permalink to &quot;PromptBridge: Cross-Model Prompt Transfer for Large Language Models&quot;">​</a></h1><p><strong>Authors</strong>: Yaxuan Wang, Quan Liu, Zhenting Wang, Zichao Li, Wei Wei, Yang Liu, Yujia Bao <strong>Affiliations</strong>: University of California Santa Cruz, Center for Advanced AI at Accenture <strong>Published</strong>: December 1, 2025 <strong>Source</strong>: <a href="https://arxiv.org/abs/2512.01420" target="_blank" rel="noreferrer">https://arxiv.org/abs/2512.01420</a><strong>arXiv ID</strong>: 2512.01420 <strong>Categories</strong>: cs.CL <strong>Corresponding Author</strong>: Yujia Bao (<a href="mailto:yujia.bao@accenture.com" target="_blank" rel="noreferrer">yujia.bao@accenture.com</a>)</p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>Large language models (LLMs) underpin applications in code generation, mathematical reasoning, and agent-based workflows. In practice, systems access LLMs via commercial APIs or open-source deployments, and the model landscape (e.g., GPT, Claude, Llama) evolves rapidly. This rapid evolution forces frequent model switches driven by capability, cost, deployment constraints, and privacy. Yet prompts are highly model-sensitive: reusing a prompt engineered for one model on another often yields substantially worse performance than a prompt optimized for the target model. We term this phenomenon <em>Model Drifting</em>. Through extensive empirical analysis across diverse LLM configurations, we show that model drifting is both common and severe. To address this challenge, we introduce PromptBridge, a training-free framework that preserves prompt effectiveness under model switches, enabling cross-model prompt transfer without costly per-task or per-model re-optimization. PromptBridge requires only a small set of alignment tasks for calibration. It first applies Model-Adaptive Reflective Prompt Evolution (MAP-RPE) to obtain task- and model-specific optimal prompts via iterative reflective refinement and quantitative evaluation. Using the resulting calibrated prompt pairs for the source and target models, PromptBridge learns a cross-model prompt mapping. At test time, i.e., for an unseen task, given a source-model prompt, this mapping directly produces an optimized prompt for the target model. Experiments in single-agent and multi-agent settings show that PromptBridge consistently improves downstream accuracy while reducing migration effort. For example, when transferring from the source model to the target model, such as o3, PromptBridge yields a 27.39% improvement on SWE-Bench and a 39.44% improvement on Terminal-Bench relative to direct transfer. The code will be available soon.</p><hr><h2 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h2><h3 id="model-drifting-問題定式化" tabindex="-1">Model Drifting 問題定式化 <a class="header-anchor" href="#model-drifting-問題定式化" aria-label="Permalink to &quot;Model Drifting 問題定式化&quot;">​</a></h3><p><strong>形式定義</strong>：給定 LLM 系統 Φ_{M,p}，當底層模型從 M_s 換為 M_t，源模型最佳 prompt p*_{M_s,T} 在目標模型上的表現：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A(M_t, T, p*_{M_s,T}) &lt; max_{p_{M_t,T}} A(M_t, T, p_{M_t,T})</span></span></code></pre></div><p>轉移缺口 Δ(M_s → M_t, T) = 目標模型自身最優 − 轉移後的表現差距。</p><h3 id="promptbridge-兩階段框架" tabindex="-1">PromptBridge 兩階段框架 <a class="header-anchor" href="#promptbridge-兩階段框架" aria-label="Permalink to &quot;PromptBridge 兩階段框架&quot;">​</a></h3><p><strong>Phase 1：MAP-RPE（Model-Adaptive Reflective Prompt Evolution）</strong></p>',13),e("ul",null,[e("li",null,"對每個 alignment task，迭代搜索：反思式精鍊（reflective refinement）+ 量化評估（island-based search）"),e("li",null,[a("輸出：一組 (p*"),e("em",{"M_t,S_i":""},"{M_s,S_i}, p*"),a(") calibrated prompt pairs")])],-1),r('<p><strong>Phase 2：Cross-Model Prompt Mapping 學習</strong></p><ul><li>從 calibration pairs 學習映射函數 T_<code>{M_s→M_t}</code></li><li>測試時：給定 unseen task 的 source prompt → 直接產出 target model 最佳 prompt</li><li><strong>Zero-shot 適應</strong>：不需要 unseen task 的評估資料</li></ul><h3 id="評估範圍" tabindex="-1">評估範圍 <a class="header-anchor" href="#評估範圍" aria-label="Permalink to &quot;評估範圍&quot;">​</a></h3><ul><li>7 個 LLMs、8 個 benchmarks</li><li>Single-agent + multi-agent 兩種設定</li><li>Local model drifting（單一 agent 換模型）+ Global model drifting（全部 agents 同換）</li></ul><hr><h2 id="關鍵數字" tabindex="-1">關鍵數字 <a class="header-anchor" href="#關鍵數字" aria-label="Permalink to &quot;關鍵數字&quot;">​</a></h2><table tabindex="0"><thead><tr><th>場景</th><th>Benchmark</th><th>PromptBridge 提升（vs. 直接轉移）</th></tr></thead><tbody><tr><td>轉移到 o3</td><td>SWE-Bench</td><td><strong>+27.39%</strong></td></tr><tr><td>轉移到 o3</td><td>Terminal-Bench</td><td><strong>+39.44%</strong></td></tr></tbody></table><p><strong>Model Drifting 嚴重性例證</strong>（HumanEval）：</p><table tabindex="0"><thead><tr><th>Source → Target</th><th>Source 最佳 prompt 在 target</th><th>Target 自身最優</th><th>Drift</th></tr></thead><tbody><tr><td>GPT-5 → Llama-3.1-70B-Instruct</td><td>68.70%</td><td>79.47%</td><td><strong>-10.77pp</strong></td></tr><tr><td>Llama-3.1-70B → GPT-5</td><td>96.95%</td><td>99.39%</td><td><strong>-2.44pp</strong></td></tr><tr><td>GPT-4o → o3（direct）</td><td>92.27%</td><td>98.37%</td><td><strong>-6.10pp</strong></td></tr></tbody></table><p><strong>校準成本</strong>：只需少量 alignment tasks，無需重新訓練模型（training-free）。</p><hr><h2 id="對-prompt-caching-management-engineering-的關聯" tabindex="-1">對 Prompt Caching / Management / Engineering 的關聯 <a class="header-anchor" href="#對-prompt-caching-management-engineering-的關聯" aria-label="Permalink to &quot;對 Prompt Caching / Management / Engineering 的關聯&quot;">​</a></h2><h3 id="prompt-caching" tabindex="-1">Prompt Caching <a class="header-anchor" href="#prompt-caching" aria-label="Permalink to &quot;Prompt Caching&quot;">​</a></h3><ul><li><strong>模型切換使快取失效</strong>：Model Drifting 的核心場景（GPT-4o → o3）等同於「快取的 prompt 在新模型上失效」——快取策略若依賴特定模型的 KV 結構，模型升級時快取全部作廢且 prompt 表現退化</li><li><strong>PromptBridge 延伸</strong>：可考慮在模型升級前預先用 MAP-RPE 校準新的 system prompt，降低 cache warm-up 期間的退化損耗</li></ul><h3 id="prompt-management" tabindex="-1">Prompt Management <a class="header-anchor" href="#prompt-management" aria-label="Permalink to &quot;Prompt Management&quot;">​</a></h3><ul><li><strong>Prompt Library 跨模型維護問題</strong>：企業若維護大量 task-specific prompts，模型切換時需全部重新優化——PromptBridge 提供一次性校準後批量轉移的解法</li><li><strong>版本控管維度</strong>：Prompt 版本應同時記錄「針對哪個模型優化」，否則版本切換時 drift 不可預測；這呼應 §R7 Surface Conflicts（不同模型的 prompt 偏好為矛盾模式）</li><li><strong>Migration Effort 量化</strong>：PromptBridge 的貢獻之一是「reducing migration effort」——提供可計算的 drift gap 指標（Δ），讓 PM 決定是否值得投入重新優化</li></ul><h3 id="prompt-engineering" tabindex="-1">Prompt Engineering <a class="header-anchor" href="#prompt-engineering" aria-label="Permalink to &quot;Prompt Engineering&quot;">​</a></h3><ul><li><strong>Model-Sensitivity 的系統性認知</strong>：不同模型因 tokenization、role tag、alignment 訓練差異（如 Llama 3 引入 <code>ipython</code> role）導致 prompt 偏好根本性不同；prompt engineer 應將「目標模型」視為 prompt 的必要 metadata</li><li><strong>MAP-RPE 作為自動化 prompt 優化器</strong>：evaluation-guided + reflection-driven + island-based 搜索，可作為 MVES（2601.22025）框架下的自動化 Fix 步驟</li><li><strong>Multi-agent 維度</strong>：全局 model drifting 在 multi-agent 系統中影響更複雜（每個 agent 的 prompt 互相依賴），需整體協調而非逐一優化</li></ul>',18)])])}const f=o(s,[["render",l]]);export{u as __pageData,f as default};
